// The GitHub Trigger payload may be wrapped in `body`.
const event = $input.first().json;
const payload = event.body ?? event;
const eventName = event.headers?.['x-github-event'] ?? '';
const repository = payload.repository;
if (!repository?.owner?.login || !repository?.name) return [];
let route = 'ignore';
let pr = null;
if ((eventName === 'pull_request' || payload.pull_request) && payload.action === 'opened') {
  pr = payload.pull_request;
  route = 'auto';
} else if ((eventName === 'issue_comment' || payload.comment) && payload.action === 'created' && payload.issue?.pull_request) {
  const command = (payload.comment?.body ?? '').trim();
  if (command === '/make_ai_review') route = 'primary';
  if (command === '/make_other_ai_review') route = 'other';
  if (route !== 'ignore') pr = payload.issue;
}
if (route === 'ignore' || !pr?.number) return [];
return [{ json: {
  route,
  owner: repository.owner.login,
  repo: repository.name,
  pr_number: pr.number,
  pr_id: pr.id,
  source_event: eventName,
  command: payload.comment?.body?.trim() ?? null,
  html_url: pr.html_url,
} }];

// Build the review context and an exact allowlist of added diff lines.
const raw = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
const files = raw.filter(file => file && typeof file.filename === 'string');
const context = $('Parse and Filter Events').first().json;
if (!files.length) throw new Error('GitHub did not return any changed files.');
const blocks = [];
const allowed_lines = {};
let budget = 22000;
for (const file of files) {
  if (!file.patch || budget <= 0) continue;
  const head = `FILE: ${file.filename} (${file.status})\n`;
  if (head.length >= budget) break;
  const lines = file.patch.split('\n');
  let currentNew = null;
  const selected = [];
  const additions = [];
  let count = head.length;
  for (const line of lines) {
    if (count + line.length + 1 > Math.min(budget, 7000)) break;
    // Display explicit new-file line coordinates next to additions.
    const annotated = currentNew !== null && line.startsWith('+') && !line.startsWith('+++')
      ? `[NEW_LINE=${currentNew}] ${line}` : line;
    selected.push(annotated);
    count += annotated.length + 1;
    const match = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(line);
    if (match) { currentNew = Number(match[1]); continue; }
    if (currentNew === null) continue;
    if (line.startsWith('+++') || line.startsWith('---') || line.startsWith('\\')) continue;
    if (line.startsWith('+')) { additions.push(currentNew); currentNew++; }
    else if (line.startsWith(' ')) currentNew++;
    else if (line.startsWith('-')) { /* old-side line only */ }
  }
  if (selected.length) {
    blocks.push(head + selected.join('\n'));
    if (additions.length) allowed_lines[file.filename] = additions;
    budget -= count;
  }
}
if (!blocks.length) throw new Error('No text patch to review (binary-only or unavailable diff).');
return [{ json: {
  ...context, changed_file_count: files.length,
  review_input: blocks.join('\n\n---\n\n'),
  allowed_lines,
  truncated: files.length >= 100 || budget < 100 || files.some(f => !f.patch)
} }];

// Parse JSON from the model, validate line anchors against parsed GitHub hunks.
const result = $input.first().json;
let text = result.text ?? result.output ?? result.response;
if (text && typeof text === 'object') text = JSON.stringify(text);
if (typeof text !== 'string') throw new Error('LLM did not return a JSON string.');
text = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let review;
try { review = JSON.parse(text); }
catch (e) { throw new Error('LLM output is not valid JSON: ' + text.slice(0, 350)); }
if (!review || typeof review !== 'object' || !Array.isArray(review.comments) || typeof review.summary !== 'string') {
  throw new Error('LLM JSON must contain summary:string and comments:array.');
}
const ctx = $('Prepare diff for review').first().json;
const valid = [];
const used = new Set();
let rejected = 0;
const rejection_details = [];
for (const candidate of review.comments.slice(0, 20)) {
  if (!candidate || typeof candidate !== 'object') { rejected++; rejection_details.push({reason:'not an object'}); continue; }
  const {path, line, body} = candidate;
  if (typeof path !== 'string' || !Number.isInteger(line) || typeof body !== 'string' || !body.trim()) { rejected++; rejection_details.push({reason:'invalid fields',path,line}); continue; }
  if (!Array.isArray(ctx.allowed_lines[path]) || !ctx.allowed_lines[path].includes(line)) { rejected++; rejection_details.push({reason:'path or line is not an added line',path,line,valid_added_lines:ctx.allowed_lines[path] ?? []}); continue; }
  const key = `${path}\u0000${line}`;
  if (used.has(key)) { rejected++; rejection_details.push({reason:'duplicate line',path,line}); continue; }
  used.add(key);
  valid.push({path, line, side: 'RIGHT', body: body.trim().slice(0, 2500)});
  if (valid.length >= 10) break;
}
const model = ctx.route === 'other' ? 'alternative' : 'primary';
let summary = review.summary.trim().slice(0, 4500) || 'Проверка изменений завершена.';
let body = `### AI Code Review (${model})\n\n${summary}`;
if (rejected) body += `\n\n_Не привязано к изменённым строкам замечаний: ${rejected} (отброшены из-за некорректных координат или дублей)._`;
if (!valid.length) body += '\n\n_Точечных замечаний к добавленным строкам нет._';
return [{json:{
  review_payload:{body,event:'COMMENT',comments:valid},
  review_comment_count:valid.length,
  rejection_details,
  pr_number:ctx.pr_number,
  model
}}];

